_ws["facts"]=[("Series","Brewers lead 2-0, best of seven"),("Game 1, Oct 23","Brewers 3, Rays 2"),("Game 2, Oct 24","Brewers 5, Rays 4. W: Abner Uribe. L: Tyler Wells. S: Aaron Ashby"),("Game 3","Mon Oct 26, 8 p.m. ET, Tropicana Field (FOX)"),("Game 3 starters","Freddy Peralta (TB) vs. Robert Gasser (MIL)"),("Game 4","Tue Oct 27, 8 p.m. ET, at Rays"),("Game 5","Wed Oct 28, at Rays, if needed"),("Games 6 and 7","Fri Oct 30 and Sat Oct 31, Milwaukee, if needed"),("History","46 of 57 teams up 2-0 went on to win (AP)")]
_ws["faq"]=[("Who won Game 2 of the 2026 World Series?","The Milwaukee Brewers beat the Tampa Bay Rays 5-4 on October 24, 2026, to lead the series 2-0."),("When is World Series Game 3?","Monday, October 26, 2026, at 8 p.m. ET at Tropicana Field in St. Petersburg, on FOX."),("Who is pitching Game 3 of the World Series?","Freddy Peralta for Tampa Bay and Robert Gasser for Milwaukee, per AP."),("How often do teams up 2-0 win the World Series?","Of the 57 previous teams to take a 2-0 lead, 46 won the title, AP reports."),("Who won Game 1 of the 2026 World Series?","The Brewers won 3-2 on October 23, 2026.")]
_ws["body"]=f'''<h2>How Game 2 played out</h2><p>Tampa Bay scored four in the first on RBI singles from Simpson and Caminero and a two-run homer by Liam Hicks. Milwaukee answered with two in the bottom of the first and one in the fourth. Sal Frelick tied it 4-4 with a sixth-inning homer off Ian Seymour, his first since July 11, and Cooper Pratt's single off Kevin Kelly in the seventh scored Brice Turang with the winning run. Aaron Ashby struck out Yandy Diaz to end it. "They believe and they don't give up," manager Pat Murphy said, per AP. Milwaukee has won seven straight.</p>
<h2>Game 3 on Monday</h2><p>The series moves to Tropicana Field. Our <a href="{R2}blog/world-series-game-3-2026-brewers-up-2-0/">Game 3 cheat sheet</a> has the starters and TV in one place, and the <a href="{R2}blog/rays-brewers-world-series-2026-preview/">series preview</a> covers both rosters.</p>
<p>Also on Monday: <a href="../wnba-finals-2026/">WNBA Finals Game 5</a> with the series tied 2-2. Tonight: the <a href="../nhl-heritage-classic-2026/">NHL Heritage Classic</a> and the <a href="../nfl/">NFL Week 8 slate</a>.</p>'''+follow("WorldSeries")
